// === Tab: mySketch.js ===
//Tree stem code forked form: https://openprocessing.org/sketch/2071621 & credit to original designer of the tree: https://openprocessing.org/sketch/1991212

//Hope you all enjoy!

let counter = 0;

function w(n) {
  if (n == null) return width;
  return width * n;
}

function h(n) {
  if (n == null) return height;
  return height * n;
}

function hsbShift(col, h, s, b) {
  return color(hue(col) + h, saturation(col) + s, brightness(col) + b);
}

function randNeg(n) {
  return (n == null) ? (random() < 0.5 ? 1 : -1) : (random() < 0.5 ? n : -n);
}

function ease(n) {
  return n ** 3;
}

class particle {
  constructor(sx, sy, sc, ss, sd, sl, ls, tag, others) {
    this.tag = tag;
    this.pos = createVector(sx, sy);
    this.col = sc;
    this.siz = 1;
    this.asiz = ss;
    this.dir = sd;
    this.spd = (this.tag == "trunk") ? 2 : random(0.25, 2);
    this.life = sl;
    this.lifespan = ls;
    this.others = others;
    this.thshift = random(-1, 1) * 0;
    this.tsshift = random(1) * 0;
    this.tbshift = random(-1) * 0;
    this.rsiz = this.asiz * this.siz;
  }

  kill() {
    let index = this.others.indexOf(this);
    if (index > -1) {
      this.others.splice(index, 1);
    }
  }

  update() {
    this.rsiz = this.asiz * this.siz;
    this.pos.add(createVector(cos(radians(this.dir)) * this.spd, sin(radians(this.dir)) * this.spd));
    this.dir += random(-1, 1) * (this.tag == "trunk" && this.siz > 0.9 ? 1 : map(this.life, 0, this.lifespan, 1, 5));
    if (random() < (this.tag == "branch" ? 0.003 : 0.005) && this.tag != "trunk") this.dir += randNeg(72) * 0;
    this.siz = lerp(this.siz, 0, random(0.015));

    if (this.rsiz < 0.1 || this.spd > this.rsiz) {
      this.kill();
    }

    this.col = hsbShift(this.col, random(this.thshift), random(this.tsshift), random(this.tbshift));

    if (random() < 0.03 && this.tag == "trunk" && this.siz < .55) {
      this.others.push(new particle(this.pos.x, this.pos.y, this.col, this.rsiz, this.dir + randNeg(random(15, 30)), this.life, this.lifespan, "branch", this.others));
    }

    if (random() < 0.01 && this.tag == "branch") {
      this.others.push(new particle(this.pos.x, this.pos.y, this.col, this.rsiz, this.dir, this.life, this.lifespan, "branch", this.others));
    }

    if (random() < map(this.siz, 0, 0.25, 0.5, 0.3) && this.tag == "branch" && this.siz < 0.25) {
      this.others.push(new particle(this.pos.x, this.pos.y, this.col, (this.siz ** 0.5) * this.rsiz, this.dir + randNeg(random(5, 20)), 0, random(this.lifespan * 0.05), "twig", this.others));
    }

    noStroke();
    fill(this.col);
    counter = round(random(3));
    if (counter == 0) circle(this.pos.x, this.pos.y, this.siz * this.asiz);

    if (this.life > this.lifespan) {
      let chance = round(random(3));
      strokeWeight(random(4));

      stroke(random(255), random(255), random(255));
      fill(random(255), random(255), random(255));
      let range = random(20, 30);

      for (let i = 0; i < 12; i++) circle(this.pos.x + random(-range, range), this.pos.y + random(-range, range), random(1, 10));

      this.kill();
    }
    this.life++;
  }
}

let PARTS = [];
let count = 10;

function setup() {
  createCanvas(1270, 600);
  background(255);

  for (let i = 0; i < 5000; i++) {
    push();
    rotate(random(3));
    stroke(random(200, 255));
    fill(random(200, 255));
    rect(random(width), random(height), random(20, 100));
    pop();
  }

  for (let i = 0; i < count; i++) {
    let startX = random(width);
    PARTS.push(new particle(startX, h(0.95), "#CD5A5A", 100, 270, 0, 500, "trunk", PARTS));
  }
}

function draw() {
  push();
  translate(0, 100);
  for (var p of PARTS) {
    for (let i = 0; i < 1; i++) p.update();
  }
  pop();

  // Revisa si ya no quedan partículas de árbol
  if (PARTS.length === 0) {
    displayMessage(); // Llama a la función para mostrar el mensaje
  }
}

function displayMessage() {
  // Dibuja las flores 🌸 y rosas 🌹 alrededor del centro
  for (let i = 0; i < 30; i++) {
    textSize(40);
    textAlign(CENTER, CENTER); // Asegura que los emojis se centren en su posición
    let angle = map(i, 0, 30, 0, TWO_PI);
    let x = width / 2 + cos(angle) * 350;
    let y = height / 2 + sin(angle) * 200;

    // --- ARREGLO 1: Se agregó la línea text() que faltaba para dibujar las flores ---
    // Alterna entre dos tipos de flores para más variedad

  }

  // Configura el estilo del texto principal
  textAlign(CENTER, CENTER);
  textSize(64);
  // --- ARREGLO 2: Se cambió el color a un turquesa verdoso ---
  fill(64, 224, 208); // Código RGB para turquesa
  stroke(0); // Borde negro para que resalte más
  strokeWeight(5);

  // Muestra el mensaje en el centro
  text("BUEN DÍA HERMOSA KELLY", width / 2, height / 2);
}

function smoothstep(start, end, amount) {
  amount = Math.max(0, Math.min(1, amount));
  return (amount * amount * (3 - 2 * amount)) * (end - start) + start;
}

